// The "What's changed" page (BetaNYC What's changed standard, Vite recipe: the page format in
// public/, copied to dist/ as-is). No dependencies: node's own test runner. `npm test`.
// The page is generated by scripts/whats_changed.py; CI also runs `render --check`.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';

const page = readFileSync(new URL('../public/whats-changed.html', import.meta.url), 'utf8');
const count = (re) => (page.match(re) || []).length;

test('one h1, and it says What\'s changed', () => {
	assert.equal(count(/<h1[\s>]/g), 1);
	assert.match(page, /<h1[^>]*>What&#x27;s changed<\/h1>|<h1[^>]*>What's changed<\/h1>/);
});

test('skip link and the five landmarks', () => {
	assert.match(page, /<a [^>]*href="#main"/);
	for (const tag of ['header', 'nav', 'main', 'footer']) assert.match(page, new RegExp(`<${tag}[\\s>]`), tag);
	assert.match(page, /<main[^>]*id="main"/);
	assert.match(page, /<html lang="en"/);
});

test('every entry has a <time> with the month spelled out', () => {
	const entries = count(/<article class="wc-entry"/g);
	assert.ok(entries >= 8, `entries: ${entries}`);
	const times = [...page.matchAll(/<time datetime="(\d{4}-\d{2}-\d{2})">([^<]+)<\/time>/g)];
	assert.equal(times.length, entries);
	for (const [, , text] of times) assert.match(text, /^[A-Z][a-z]+ \d{1,2}, \d{4}$/);
});

test('the filter is a fieldset with a legend, hidden until its script runs, with a polite live region', () => {
	assert.match(page, /<div class="wc-filters" hidden>/);
	assert.match(page, /<legend>Show changes to<\/legend>/);
	assert.equal(count(/<input type="checkbox"/g), 4);
	assert.match(page, /role="status" aria-live="polite"/);
	assert.match(page, /box\.hidden = false/);
});

test('the map links to the page from its footer', () => {
	const app = readFileSync(new URL('../src/App.svelte', import.meta.url), 'utf8');
	assert.match(app, /<footer[\s\S]*href="\.\/whats-changed\.html"[\s\S]*<\/footer>/);
});

test('a build copies the page into dist/', { skip: !existsSync(new URL('../dist/index.html', import.meta.url)) && 'no dist/; run npm run build' }, () => {
	const built = readFileSync(new URL('../dist/whats-changed.html', import.meta.url), 'utf8');
	assert.equal(built, page);
});
